# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: emit
def emit(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: sift
def sift(xs, offset=-1):
    return [v + offset for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: digest
def digest(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(fold(sift(emit(intake(raw)))))

